def seed():
    db = SessionLocal()
    try:
        if db.query(City).count() > 0:
            print("数据库已有数据，跳过初始化")
            return
        for c in cities_data:
            city = City(**c)
            db.add(city)
        db.flush()
        # Deduplicate cities: keep the first occurrence, merge related records
        dupes = db.query(City.name, func.count(City.id)).group_by(City.name).having(func.count(City.id) > 1).all()
        for name, cnt in dupes:
            cities = db.query(City).filter(City.name == name).order_by(City.id).all()
            keep = cities[0]
            for dup in cities[1:]:
                db.query(House).filter(House.city_id == dup.id).update({"city_id": keep.id})
                db.query(Review).filter(Review.city_id == dup.id).update({"city_id": keep.id})
                db.query(Guide).filter(Guide.city_id == dup.id).update({"city_id": keep.id})
                db.delete(dup)
            print(f"  合并重复城市: {name} (保留ID={keep.id}, 删除{cnt-1}个重复)")
        db.flush()
        # Build name→id lookup for house/review assignment
        city_map = {c.name: c.id for c in db.query(City).all()}
        # Add houses (resolve _city_name for any entry that has it)
        for h in houses_data:
            if "_city_name" in h:
                h["city_id"] = city_map.get(h["_city_name"], h.get("city_id"))
            if "city_id" not in h:
                continue
            house = House(**{k:v for k,v in h.items() if not k.startswith("_")})
            db.add(house)
        db.flush()
        for r in reviews_data:
            if "_city_name" in r:
                r["city_id"] = city_map.get(r["_city_name"], r.get("city_id"))
            if "city_id" not in r:
                continue
            review = Review(**{k:v for k,v in r.items() if not k.startswith("_")})
            db.add(review)
        for g in guides_data:
            guide = Guide(**g)
            db.add(guide)
        db.commit()
        print(f"初始化完成：{city_map}")
        print(f"  {len(city_map)}个城市, {len(houses_data)}个房源, {len(reviews_data)}条评价, {len(guides_data)}篇攻略")
    finally:
        db.close()

if __name__ == "__main__":
    seed()
